import{x as t,o as a,c as d,a9 as r}from"./chunks/framework.DxG24V0C.js";const s="/agentsrc/images/deepseek/article-01-architecture.svg",k=JSON.parse('{"title":"DeepSeek Harness 源码精读","description":"","frontmatter":{"title":"DeepSeek Harness 源码精读"},"headers":[],"relativePath":"deepseek/index.md","filePath":"deepseek/index.md","lastUpdated":1787409644000}'),o={name:"deepseek/index.md"};function n(i,e,l,p,c,h){return a(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="deepseek-harness-源码精读" tabindex="-1">DeepSeek Harness 源码精读 <a class="header-anchor" href="#deepseek-harness-源码精读" aria-label="Permalink to &quot;DeepSeek Harness 源码精读&quot;">​</a></h1><blockquote><p>DeepSeek 开源通用 agent harness 源码深度解析</p></blockquote><p>这里是「<strong>DeepSeek Harness 源码精读</strong>」专栏，逐层拆解 DeepSeek 这套「一切皆插件」的通用 agent 引擎——从插件框架、主循环、会话日志，到能力缝体系、长会话扩展与生态桥接。</p><p>无论你是想理解「插件式 agent 运行时」该如何设计，还是想看看一个能把模型适配、上下文、压缩、子代理全部做成可换缝的引擎长什么样，都能在这里找到答案。</p><h2 id="关于本系列" tabindex="-1">关于本系列 <a class="header-anchor" href="#关于本系列" aria-label="Permalink to &quot;关于本系列&quot;">​</a></h2><p>本系列基于 <strong><code>dsh-v0.1.0-rc.7</code></strong> 编写。项目处于 developer preview，迭代很快，文中机制以该基线为准。</p><ul><li><strong>源码层</strong>：<code>packages/</code> 约 <strong>40+ 万行</strong> TypeScript、<strong>220+ 个 package</strong>（按组分布：core / api / llm / shell / subprocess / fs / lsp / web / compaction / context / subagent / hooks / session / workflow …）</li><li><strong>技术底座</strong>：vendored Cordis（事件 / 插件 / 生命周期）+ TypeScript</li><li><strong>设计主线</strong>：capability 缝（Service Definition / Provider / Consumer）+ 会话日志（&quot;模型可见 ⟺ 可重建&quot;）+ 一切皆插件</li><li><strong>特色</strong>：每篇都附「OpenCode / Codex / Claude Code 对比」，以及「可变缝」视角的统一分析</li></ul><h2 id="文章列表" tabindex="-1">文章列表 <a class="header-anchor" href="#文章列表" aria-label="Permalink to &quot;文章列表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>文章</th><th>类型</th><th>字数（约）</th></tr></thead><tbody><tr><td>1</td><td><a href="/agentsrc/deepseek/01-overview.html">DeepSeek Harness 全景：一个&quot;一切皆插件&quot;的通用 agent harness</a></td><td>源码解析</td><td>~8,000</td></tr><tr><td>2</td><td><a href="/agentsrc/deepseek/02-cordis.html">Cordis 组合框架：几十个 package 靠什么拼成一个 agent</a></td><td>源码解析</td><td>~12,000</td></tr><tr><td>3</td><td><a href="/agentsrc/deepseek/03-agent-loop.html">Agent 接口与默认 loop：一个 agent 到底怎么跑一个回合</a></td><td>源码解析</td><td>~11,000</td></tr><tr><td>4</td><td><a href="/agentsrc/deepseek/04-session-log.html">会话日志与上下文投影：模型看到的上下文从哪来</a></td><td>源码解析</td><td>~9,000</td></tr><tr><td>5</td><td><a href="/agentsrc/deepseek/05-tools-pipeline.html">工具系统与执行管线：模型怎么把一个工具请求变成真实行动</a></td><td>源码解析</td><td>~10,000</td></tr><tr><td>6</td><td><a href="/agentsrc/deepseek/06-capability-seams.html">Capability 缝体系：为什么换一个实现能牵一发动全身</a></td><td>源码解析</td><td>~10,000</td></tr><tr><td>7</td><td><a href="/agentsrc/deepseek/07-compaction-context-subagent.html">压缩 / 上下文注入 / 子代理：装配式的长会话扩展</a></td><td>源码解析</td><td>~10,000</td></tr><tr><td>8</td><td><a href="/agentsrc/deepseek/08-self-modification-hooks.html">自改 / hooks 桥 / 生态：agent 学会改自己、也接得住别家的协议</a></td><td>源码解析</td><td>~10,000</td></tr></tbody></table><h2 id="整体架构速览" tabindex="-1">整体架构速览 <a class="header-anchor" href="#整体架构速览" aria-label="Permalink to &quot;整体架构速览&quot;">​</a></h2><p>以下是 dsh 的装配链全景：空 root → bundle 层 → patch 覆盖 → 装配成的插件树，再到 CLI / Web 两个产品壳。</p><p><img src="'+s+'" alt="dsh 装配链架构：profile / bundle 分层组装一棵插件树"></p>',12)])])}const m=t(o,[["render",n]]);export{k as __pageData,m as default};
